create extension if not exists pgcrypto;
create table public.families (id uuid primary key default gen_random_uuid(), name text not null default 'Our Christmas', invite_code text unique not null default upper(encode(gen_random_bytes(9),'hex')), created_by uuid not null references auth.users(id));
create table public.members (family_id uuid not null references public.families(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, primary key(family_id,user_id));
create table public.people (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, name text not null check(length(trim(name))>0), budget numeric(12,2) not null default 0 check(budget>=0), created_at timestamptz default now());
create table public.gifts (id uuid primary key default gen_random_uuid(), person_id uuid not null references public.people(id) on delete cascade, name text not null check(length(trim(name))>0), cost numeric(12,2) not null default 0 check(cost>=0), status text not null default 'planned' check(status in ('planned','purchased','wrapped')), notes text not null default '', created_at timestamptz default now());
create index on public.members(user_id);
create index on public.people(family_id);
create index on public.gifts(person_id);
create function public.is_family_member(fid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.members where family_id=fid and user_id=(select auth.uid())); $$;
revoke all on function public.is_family_member(uuid) from public;
grant execute on function public.is_family_member(uuid) to authenticated;
create function public.create_family(family_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare fid uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if; insert into public.families(name,created_by) values (left(coalesce(nullif(trim(family_name),''),'Our Christmas'),100),auth.uid()) returning id into fid; insert into public.members values(fid,auth.uid()); return fid; end $$;
create function public.join_family(code text) returns uuid language plpgsql security definer set search_path='' as $$ declare fid uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select id into fid from public.families where invite_code=upper(trim(code)); if fid is null then raise exception 'Invalid invite code'; end if; insert into public.members values(fid,auth.uid()) on conflict do nothing; return fid; end $$;
revoke all on function public.create_family(text), public.join_family(text) from public;
grant execute on function public.create_family(text), public.join_family(text) to authenticated;
alter table public.families enable row level security;
alter table public.members enable row level security;
alter table public.people enable row level security;
alter table public.gifts enable row level security;
create policy family_read on public.families for select to authenticated using (public.is_family_member(id));
create policy member_read on public.members for select to authenticated using (public.is_family_member(family_id));
create policy people_read on public.people for select to authenticated using (public.is_family_member(family_id));
create policy people_insert on public.people for insert to authenticated with check (public.is_family_member(family_id));
create policy people_update on public.people for update to authenticated using (public.is_family_member(family_id)) with check (public.is_family_member(family_id));
create policy people_delete on public.people for delete to authenticated using (public.is_family_member(family_id));
create policy gifts_read on public.gifts for select to authenticated using (exists(select 1 from public.people p where p.id=person_id and public.is_family_member(p.family_id)));
create policy gifts_insert on public.gifts for insert to authenticated with check (exists(select 1 from public.people p where p.id=person_id and public.is_family_member(p.family_id)));
create policy gifts_update on public.gifts for update to authenticated using (exists(select 1 from public.people p where p.id=person_id and public.is_family_member(p.family_id))) with check (exists(select 1 from public.people p where p.id=person_id and public.is_family_member(p.family_id)));
create policy gifts_delete on public.gifts for delete to authenticated using (exists(select 1 from public.people p where p.id=person_id and public.is_family_member(p.family_id)));
revoke all on public.families,public.members,public.people,public.gifts from anon;
grant select on public.families,public.members to authenticated;
grant select,insert,update,delete on public.people,public.gifts to authenticated;
-- Enable postgres changes for live updates (also possible in Dashboard > Database > Publications)
alter publication supabase_realtime add table public.people;
alter publication supabase_realtime add table public.gifts;
